 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]]

    def paint(r, c, value):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = value

    # The 2 motif's midpoint is 4 when a 3 or 6 lies in its column; its
    # descending-left continuation uses the same color.
    for r, c, color in points:
        if color == 2:
            mid_c = c - 2
            mid_color = 4 if any(v in (3, 6) and cc == mid_c for _, cc, v in points) else 5
            paint(r, c - 4, 2)
            paint(r, c - 3, 5)
            paint(r, mid_c, mid_color)
            paint(r, c - 1, 5)
            if mid_color == 4:
                rr, cc = r + 1, mid_c - 1
                while rr < h and cc >= 0:
                    paint(rr, cc, 4)
                    rr += 1
                    cc -= 1

    for r, c, color in points:
        if color == 1:
            paint(r, c + 1, 5)
            paint(r, c + 2, 5)
            paint(r - 1, c + 2, 1)
        elif color == 3:
            paint(r + 1, c, 5)
            paint(r + 2, c, 5)
            paint(r + 3, c, 3)
        elif color == 6:
            # Six-cell upward extension: five 5s and a terminal 6.
            for distance in range(1, 6):
                paint(r - distance, c, 5)
            paint(r - 6, c, 6)
    return out
